class Solution {
public:
    int wordCount(vector<string>& startWords, vector<string>& targetWords) {
        unordered_set<int> startSet;
        for (const string& w : startWords) {
            int mask = 0;
            for (char ch : w) mask |= (1 << (ch - 'a'));
            startSet.insert(mask);
        }
        int ans = 0;
        for (const string& w : targetWords) {
            int mask = 0;
            for (char ch : w) mask |= (1 << (ch - 'a'));
            for (char ch : w) {
                int subMask = mask ^ (1 << (ch - 'a'));
                if (startSet.count(subMask)) {
                    ans++;
                    break;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int wordCount(String[] startWords, String[] targetWords) {
        Set<Integer> startSet = new HashSet<>();
        for (String w : startWords) {
            int mask = 0;
            for (char ch : w.toCharArray()) mask |= (1 << (ch - 'a'));
            startSet.add(mask);
        }
        int ans = 0;
        for (String w : targetWords) {
            int mask = 0;
            for (char ch : w.toCharArray()) mask |= (1 << (ch - 'a'));
            for (char ch : w.toCharArray()) {
                int subMask = mask ^ (1 << (ch - 'a'));
                if (startSet.contains(subMask)) {
                    ans++;
                    break;
                }
            }
        }
        return ans;
    }
}

var wordCount = function(startWords, targetWords) {
    const startSet = new Set();
    for (const w of startWords) {
        let mask = 0;
        for (let i = 0; i < w.length; i++) mask |= (1 << (w.charCodeAt(i) - 97));
        startSet.add(mask);
    }
    let ans = 0;
    for (const w of targetWords) {
        let mask = 0;
        for (let i = 0; i < w.length; i++) mask |= (1 << (w.charCodeAt(i) - 97));
        for (let i = 0; i < w.length; i++) {
            const subMask = mask ^ (1 << (w.charCodeAt(i) - 97));
            if (startSet.has(subMask)) {
                ans++;
                break;
            }
        }
    }
    return ans;
};
